'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cite=keys=>`<p class="source">${keys.map(k=>`<a href="${sources[k].url}" target="_blank" rel="noopener">${sources[k].name} ↗</a>`).join('<br>')}</p>`;
const pic=(id,cls='')=>{const i=images.find(i=>i.id===id&&i.path);return i?`<figure class="${cls}"><button class="image-button" data-image="${id}" aria-label="Bild vergrössern: ${esc(i.caption)}"><img src="${i.path}" alt="${esc(i.caption)}" loading="lazy"></button><figcaption>${esc(i.caption)} <a href="${i.source}" target="_blank" rel="noopener">Bildnachweis ↗</a></figcaption></figure>`:''};
const timeline=[['1827','Johanna Heusser wird geboren','Spyris Biografie gehört in die Schweiz des 19. Jahrhunderts. Ihre spätere Autorschaft entsteht in einem religiös und literarisch geprägten Umfeld.'],['1871','Beginn der Publikationen','Ein Blatt auf Vrony’s Grab erscheint. Heidi ist Teil eines grösseren Werks mit Erzählungen für Kinder und Erwachsene.'],['1880 / 1881','Zwei Heidi-Romane','Lehr- und Wanderjahre und Heidi kann brauchen, was es gelernt hat: Rückkehr, Bildung und Fürsorge bilden zusammen einen Bogen.'],['1920','Japanische Übersetzung','Yaeko Nogami übersetzt über das Englische. Internationale Rezeption beginnt lange vor dem Anime.'],['1937 → 1955','Kino und nationale Selbstbilder','Hollywood-Kinderstar, Schweizer Authentizitätsanspruch und touristisch verwertbare Landschaftsbilder treffen aufeinander.'],['1974 → 1978','Das serielle Fernsehkind','Anime und Realserie schaffen wiederkehrende Begegnungen. Unterschiedliche Sprach- und Musikfassungen prägen Erinnerungen.'],['2001 → 2015','Neue Gegenwart, neue Zukunft','Imboden aktualisiert die Lebenswelt; Gsponer und Volpe erzählen im historischen Rahmen mit einer stärkeren Zukunftsperspektive für Heidi.'],['2022 → 2025','Parodie, Archiv und Ökologie','Mad Heidi (2022), UNESCO-Archivaufnahme (2023) und das Luchs-Abenteuer (2025) zeigen gleichzeitig Bewahrung und Neuaneignung.']];
const archiveTable=rows=>`<div class="table-wrap"><table><caption>Jahr, Titel und quellenkritische Einordnung</caption><thead><tr><th scope="col">Jahr / Ausgabe</th><th scope="col">Titel</th><th scope="col">Einordnung & Nachweis</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${esc(r[0])}</th><td>${esc(r[1])}</td><td>${esc(r[2])}<br><a href="${esc(r[3])}" target="_blank" rel="noopener">Nachweis öffnen ↗</a></td></tr>`).join('')}</tbody></table></div>`;
const app=$('#app');
app.innerHTML=`
<section id="start" class="intro"><div><p class="eyebrow">LITERATUR · FILM · KULTURGESCHICHTE</p><h1>Heidi.<br>Eine Weltgeschichte.</h1><p class="lead">Ein Kind zwischen Alp und Grossstadt. Eine Geschichte zwischen Glauben, Heimatsehnsucht und globaler Popkultur.</p><p>Wie verändert sich Heidi, wenn andere Zeiten, Länder und Medien ihre Geschichte erzählen?</p><div class="intro-actions"><a class="button" href="#wege">Lernweg wählen ↗</a><a href="#kino">Direkt zu den Verfilmungen →</a></div><div class="metrics"><span><b>${films.length}</b> Film- & Serienproduktionen</span><span><b>10</b> Lernwerkstätten</span><span><b>4</b> Ausgangsdokumente</span></div></div><aside class="hero-image">${pic('hero','hero-figure')}<div class="hero-label"><span>GRAUBÜNDEN / EIN REALER ORT</span><p>Eine Landschaft.<br>Unzählige Bilder von Heimat.</p></div></aside></section>
<section id="wege"><div class="section-heading"><div><p class="eyebrow">ORIENTIERUNG</p><h2>Welchen Weg gehst du?</h2></div><p>Für Gymnasium und FMS.<br>Alle Stationen lassen sich auch einzeln bearbeiten.</p></div><div class="grid paths"><article class="card"><span class="number">01 / KOMPAKT · 2 LEKTIONEN</span><h3>Hinter die Idylle schauen</h3><p>Romanüberblick → Werkstatt 1 → Filmvergleich 1937 / 1974 / 2015 → Offener Lerncheck.</p><p class="small">Du unterscheidest Original, Bearbeitung und eigene Erinnerung und belegst eine erste Vergleichsthese.</p><a href="#roman">Mit dem Roman beginnen →</a></article><article class="card"><span class="number">02 / FILMFOKUS · 4–6 LEKTIONEN</span><h3>Wie Filme Heidi erzählen</h3><p>Filmarchiv → Dramaturgielabor → Werkstätten 5 und 6 → Szenenprotokoll.</p><p class="small">Du erklärst, wie Konflikt, Perspektive, Zeit und audiovisuelle Mittel zusammenwirken.</p><a href="#kino">Ins Filmarchiv →</a></article><article class="card"><span class="number">03 / FORSCHUNG · 8–12 LEKTIONEN</span><h3>Eine Ikone untersuchen</h3><p>Historische Kontexte → drei Wahlwerkstätten → eigene Adaption oder kleine Ausstellung.</p><p class="small">Du setzt Quellen kritisch zueinander in Beziehung und entwickelst eine begründete eigene Position.</p><a href="#stationen">Werkstätten auswählen →</a></article></div><p class="small">Zeitangaben ohne vollständige Filmsichtungen. Für Filmszenen eine legal verfügbare Fassung nutzen und Sprache, Schnittfassung sowie Zeitcode dokumentieren. Die Player bieten Trailer, Szenen, Vorspänne und begrenzte Ausschnitte aus externen Gesamtfilmen. Sprache, Schnittfassung und Zeitcode gehören ins Szenenprotokoll.</p></section>
<section id="roman" class="blue-section"><p class="eyebrow">DER ROMAN · MEHR ALS EIN BERGMÄRCHEN</p><h2>Die Idylle hat Risse.</h2><div class="split"><div class="prose"><p>1880 erscheint <em>Heidis Lehr- und Wanderjahre</em>, 1881 folgt <em>Heidi kann brauchen, was es gelernt hat</em>. Die beiden Bücher verbinden das Schicksal eines Kindes mit der Veränderung seiner Umgebung. Ein Waisenkind findet beim Grossvater ein Zuhause, wird nach Frankfurt gebracht und leidet dort unter Heimweh. Seine Rückkehr beendet den ersten grossen Spannungsbogen. Im zweiten Band besucht Klara die Alp und lernt gehen.</p><p>Doch «Berg = gut, Stadt = schlecht» greift zu kurz. Im Dorf begegnen uns Armut, Ausgrenzung und begrenzter Bildungszugang. In Frankfurt ermöglichen die Grossmutter Sesemann und der Arzt Hilfe. Die beiden Räume stehen in Spannung, sind aber auch aufeinander angewiesen.</p><p>Die Leitfrage lautet deshalb nicht nur: <em>Wo ist Heidi glücklich?</em> Sondern auch: Wer darf über sie entscheiden, welche Beziehungen tragen sie und welche Ordnung stellt das Ende wieder her?</p>${cite(['dossier','klimek'])}</div>${pic('buch-alp','book-image')}</div><div class="storyline" aria-label="Handlungsstruktur"><div><b>1 · Ankommen</b><span>Heidi gewinnt einen Lebensraum.</span></div><div><b>2 · Weggebracht werden</b><span>Andere bestimmen ihren Ort.</span></div><div><b>3 · Leiden erkennen</b><span>Heimweh wird ernst genommen.</span></div><div><b>4 · Zurückkehren</b><span>Auch der Grossvater findet Anschluss.</span></div><div><b>5 · Gelerntes weitergeben</b><span>Klara, Grossmutter und Arzt profitieren.</span></div></div><div class="grid concepts"><article><h3>Bildung als Beziehung</h3><p>Heidi lernt lesen und kann der blinden Grossmutter vorlesen. Wissen erhält seinen Wert in der Fürsorge. Die Frage nach selbstbestimmter Bildung entsteht aus heutiger Perspektive zusätzlich.</p></article><article><h3>Religion als Handlungskraft</h3><p>Gebet, geistliche Lieder und das Gleichnis vom verlorenen Sohn motivieren Trost und Rückkehr. Klimek liest den Glaubensweg des Grossvaters als Geschichte für erwachsene Mitlesende.</p></article><article><h3>Versöhnung mit Grenzen</h3><p>Materielle Not wird durch Hilfe gemildert. Die soziale Ordnung wird nicht grundsätzlich aufgehoben. Zu prüfen bleibt, welche Abhängigkeiten das glückliche Ende bewahrt.</p></article></div></section>
<section id="spyri"><p class="eyebrow">FORSCHUNGSFENSTER / SPYRI UM 1880</p><h2>Eine Autorin hinter der Ikone.</h2><div class="grid"><article class="card"><h3>Mehrere Leser zugleich</h3><p>Der Untertitel der frühen Ausgaben richtet sich an Kinder und an Menschen, die Kinder lieb haben. Klimek nimmt diese doppelte Adresse ernst: Erwachsene können im Grossvater eine Geschichte von Enttäuschung, Glaubenszweifel und Vergebung lesen, während Kinder Heidis Erfahrungen verfolgen. Eine Verfilmung entscheidet neu, wie viel Eigengewicht die Erwachsenen erhalten.</p>${cite(['klimek'])}</article><article class="card"><h3>Welche Zukunft für Mädchen?</h3><p>Mikotas Beitrag über <em>Sina</em> (1884) zeigt, dass Studium, Erwerbsarbeit und weibliche Lebensentwürfe schon in Spyris Werk umstritten sind. Die Studentin wird schliesslich zur Ehe geführt; zugleich schildert der Text ihre Wünsche und die verletzenden Erfahrungen an der Universität. Das macht eine pauschale Einordnung Spyris als bloss fortschrittlich oder bloss rückständig unzureichend.</p><p class="source"><a href="quellen/Heidiundmehr.pdf#page=141" target="_blank" rel="noopener">Jana Mikota: Von Gelehrsamkeit, Mütterlichkeit und Genügsamkeit (2026), S. 135–148, besonders 142–145 ↗</a></p></article><article class="card"><h3>Berühmt – aber auch gelesen?</h3><p>Leskau und Nieberle unterscheiden die allgegenwärtige Figur von der literarischen Aufmerksamkeit für ihre Autorin. Wer Heidi aus Serie, Werbung oder Tourismus kennt, kennt nicht notwendig den Roman. Popularität und literarische Kanonisierung hängen zusammen, sind aber nicht dasselbe.</p><p><b>Transferfrage:</b> Was verändert sich, wenn eine Adaption mit den bereits bekannten Bildern wirbt, statt neue Leserinnen und Leser zu Spyri zurückzuführen?</p>${cite(['leskau'])}</article></div></section><section id="geschichte"><p class="eyebrow">HISTORISCH VERORTEN</p><h2>Jede Heidi hat ihre Zeit.</h2><p class="section-intro">Erzählte Zeit, Produktionszeit und Rezeptionszeit sind verschieden. Ein Film von 1952 kann im 19. Jahrhundert spielen und vom Nachkriegspublikum nochmals anders verstanden werden.</p><div class="timeline">${timeline.map(t=>`<article><span>${t[0]}</span><div><h3>${t[1]}</h3><p>${t[2]}</p></div></article>`).join('')}</div>${cite(['klimek','bando','tomkowiak','unesco'])}<div class="callout"><h3>Eine historische Erklärung braucht ein Bindeglied.</h3><p>«Der Film entstand nach dem Krieg» genügt nicht als Interpretation. Nennt zusätzlich eine Form, ein Motiv oder ein Rezeptionszeugnis: etwa den Verleihtitel «Sehnsucht nach der Heimat», einen Pressebericht oder die Anordnung einer Szene. Erst dann lässt sich der historische Zusammenhang begründen.</p></div></section>
<section id="kino" class="cinema"><div class="section-heading"><div><p class="eyebrow">DAS FILMARCHIV · 1920–2025</p><h2>Eine Figur.<br>Viele Erzählweisen.</h2></div><p>${films.length} recherchierte Produktionen.<br>Zusätzlich ${filmVariants.length} Schnittfassungen und Ausgaben.</p></div><p class="section-intro">Die Recherche erfasst Romanadaptionen, Serien, Fortsetzungen, Kurzfilme und freie Bearbeitungen weltweit. Schnittfassungen, Randfälle und angekündigte Produktionen stehen in eigenen Registern. Die Vertiefungen stützen sich auf die bereitgestellte Forschung und zusätzliche Film- und Produktionsquellen. Bei weniger ausführlich dokumentierten Fassungen sind Deutungen als Prüfaufträge formuliert. Es wird keine vollständige Sichtung aller Filme behauptet.</p><p class="small"><a href="Filmografie_Heidi.json" download>Gesamtes Filmverzeichnis mit Quellen herunterladen (JSON)</a></p><div class="archive-jumps"><a href="#film-grid">Produktionen</a><a href="#schnittfassungen">Schnittfassungen & Ausgaben</a><a href="#recherchefaelle">Grenzfälle & offene Zuordnungen</a><a href="#angekuendigt">Angekündigte Serien</a></div><label class="film-search-label" for="film-search">Produktionen nach Titel, Jahr, Land oder Regie suchen<input id="film-search" type="search" placeholder="z. B. BBC, 1958, Musical, Japan …"></label><div class="filters" role="group" aria-label="Filmarchiv filtern">${['Alle','Kino','Fernsehen','Animation','Neudeutung','Kurzfilm','Kunstfilm'].map((x,i)=>`<button data-filter="${x}" aria-pressed="${i===0}">${x}</button>`).join('')}<span id="film-count" role="status">${films.length} Produktionen</span></div>${renderClipCoverage()}<div id="film-grid" class="film-grid"></div><div class="archive-note"><strong>Fassungen nicht verwechseln.</strong> Produktionsjahr, Synchronfassung und spätere Veröffentlichung können unterschiedliche Daten tragen. Der Anime stammt von 1974; eine spätere Kinokompilation ist nicht dieselbe Werkfassung. Ebenso sind der Realfilm und die CGI-Serie von 2015 zwei eigenständige Produktionen. Karpis KI-Trailer von 2023 steht bei den digitalen Aneignungen, nicht als vollständiger Film im Archiv. <b>Recherchegrenze:</b> Erfasst sind alle in dieser Recherche identifizierten Produktionen und weiteren Hinweise; eine lückenlose Weltfilmografie lässt sich angesichts widersprüchlicher Kataloge und verschollener Kopien nicht garantieren. Ein Nachweis ist noch kein abspielbarer Film. Bei externen Filmangeboten können Sprache, Region, Anmeldung und Kosten variieren.</div>
<div id="schnittfassungen" class="archive-register"><p class="eyebrow">FASSUNG IST NICHT NEUPRODUKTION</p><h3>Aus einer Serie werden viele Filme.</h3><p>Diese ${filmVariants.length} Einträge machen Schnittfassungen und Heimvideoausgaben sichtbar. Jahresangaben einer DVD oder Synchronfassung bezeichnen nicht zwingend die Erstherstellung. Die Liste dient auch als Arbeitsgrundlage für den Vergleich von Kürzung, neuer Musik und veränderter Episodenfolge.</p>${archiveTable(filmVariants.map(r=>[r[0],r[1],r[2]+' Clipstatus: Noch kein verifizierter, ausgabenspezifischer Ausschnitt eingebunden.',r[3]]))}<div class="film-task"><b>Montage-Labor</b><p>Wählt zehn Minuten aus der Serie und die entsprechende Passage einer Kompilation. Erstellt eine Liste: erhalten, gekürzt, umgestellt, neu erklärt. Formuliert eine These dazu, wie sich dadurch die Motivation einer Figur oder das Erzähltempo verändert.</p></div></div>
<div id="recherchefaelle" class="archive-register"><p class="eyebrow">TRANSPARENTE FILMOGRAFIE</p><h3>Grenzfälle und noch offene Zuordnungen.</h3><p>Auch unsichere Treffer bleiben auffindbar. Sie werden nicht stillschweigend zu gesicherten eigenständigen Verfilmungen erklärt.</p>${archiveTable(filmResearch)}</div>
<div class="archive-register" id="dokumentarfilm"><p class="eyebrow">FILM ÜBER DEN MYTHOS</p><h3>Dokumentarische Begleitung.</h3>${archiveTable(filmDocumentaries)}</div><div id="angekuendigt" class="archive-register"><p class="eyebrow">AUSBLICK · RECHERCHESTAND SEPTEMBER 2026</p><h3>Angekündigt, noch nicht als fertiger Film analysiert.</h3>${archiveTable(filmUpcoming)}</div></section>
<section id="labor"><p class="eyebrow">DRAMATURGIELABOR</p><h2>Was treibt die Geschichte an?</h2><p class="section-intro">Wähle zwei Fassungen. Die Matrix formuliert Ausgangspunkte für deine Szenenanalyse; sie ersetzt keine genaue Beobachtung.</p><div class="compare-controls"><label>Fassung A<select id="compare-a">${films.map(f=>`<option value="${f.id}" ${f.id==='1937'?'selected':''}>${f.year} · ${f.title} · ${f.director}</option>`).join('')}</select></label><label>Fassung B<select id="compare-b">${films.map(f=>`<option value="${f.id}" ${f.id==='1974'?'selected':''}>${f.year} · ${f.title} · ${f.director}</option>`).join('')}</select></label></div><div id="comparison" aria-live="polite"></div><div class="grid lenses"><article><span class="number">01 / KONFLIKT</span><h3>Wer will was?</h3><p>Unterscheide äussere Hindernisse, innere Konflikte und soziale Regeln. Eine böse Einzelperson erzeugt eine andere Geschichte als eine Ordnung, die kindliche Bedürfnisse übersieht.</p></article><article><span class="number">02 / PERSPEKTIVE</span><h3>Wessen Wissen zählt?</h3><p>Fokalisierung bezeichnet die Bindung von Wahrnehmung und Wissen. Im Film können Blickanschlüsse, subjektive Bilder oder Szenen ohne Heidi Informationen verteilen.</p></article><article><span class="number">03 / ZEIT</span><h3>Was darf dauern?</h3><p>Raffung überspringt Zeit; eine Szene entfaltet einen Moment; Wiederholung macht Alltag vertraut. Ein Cliffhanger kann eine kleine offene Frage sein, nicht nur eine Gefahr.</p></article><article><span class="number">04 / RAUM</span><h3>Wie handelt die Umgebung mit?</h3><p>Fenster, Türen, Wege, Kleidung und Möbel ermöglichen oder verhindern etwas. Beschreibe ihre konkrete Funktion, bevor du ihnen eine symbolische Bedeutung gibst.</p></article><article><span class="number">05 / TON UND BILD</span><h3>Wie werden wir gelenkt?</h3><p>Einstellungsgrösse, Schnitt, Farbe, Geräusch und Musik können Nähe erzeugen oder Abstand schaffen. Bei 1974 unbedingt die Sprach- und Musikfassung nennen.</p></article><article><span class="number">06 / SCHLUSS</span><h3>Was gilt als gelöst?</h3><p>Rückkehr, Vergebung, Gehenlernen, eigenes Schreiben oder Rettung eines Tiers setzen andere Ziele. Prüfe, welche Konflikte am Ende fortbestehen.</p></article></div>
<div class="deep-dive"><div><p class="eyebrow">FALLSTUDIE / TAKAHATA</p><h3>Langsamkeit ist eine Entscheidung.</h3><p>Takahata erklärt, dass er nicht rasch nach Frankfurt springen wollte, um möglichst bald Rührung zu erzeugen. Erst das ausführliche Leben auf der Alp macht deren späteren Verlust für das Publikum nachvollziehbar. Die Frage, wie Heidi auf den fremden Grossvater reagiert, reicht als episodische Spannung.</p><p>Seine Eingriffe verändern auch die Moral der Geschichte: Peter soll ein Freund sein, mit dem Kinder ein Jahr verbringen wollen. Die Grossmutter befreit die Mädchen aus Enge; Rottenmeier wird auf der Alp zur unsicheren Besucherin. Das Publikum kennt sich dort besser aus als sie. Komik verändert so das Machtverhältnis.</p><p>Takahatas Warnung zu ausländischen Musikfassungen lässt sich produktiv mit Stetters Analyse verbinden: Wenn eine untersuchte Szene pathetische Musik verwendet, widerlegt das nicht automatisch die erklärte Absicht eines sparsamen Musikeinsatzes. Zuerst muss die Fassung geklärt werden.</p>${cite(['takahata','stetter'])}</div>${pic('1974','wide-image')}</div>
<div class="callout"><h3>Eine Vergleichsthese mit Beleg</h3><p>«Während Fassung A den Konflikt durch <em>…</em> löst, setzt Fassung B auf <em>…</em>. Das zeigt sich an <em>…</em> [Zeitcode / konkrete Beobachtung]. Im Produktions- oder Rezeptionskontext <em>…</em> wird diese Verschiebung verständlich. Eine alternative Deutung wäre <em>…</em>.»</p></div></section>
<section id="bilder" class="blue-section"><p class="eyebrow">BILDER LESEN</p><h2>Die erste Deutung kommt oft vor dem Text.</h2><div class="gallery">${pic('buch','gallery-image')}${pic('buch-alp','gallery-image')}${pic('buch-klara','gallery-image')}</div><div class="split"><div><h3>Beobachten → deuten → prüfen</h3><p>Die historische Illustration beim Grossvater und das Bild mit Klara gestalten Beziehungen durch Körpergrösse, Blickrichtung, Kleidung und räumliche Nähe. Sie sind Deutungen aus einer bestimmten Ausgabe – keine neutralen Abbilder von Spyris Sprache.</p><p>Untersuche zunächst sichtbare Merkmale. Formuliere erst dann, welches Kindheitsbild entsteht. Prüfe deine These an einer passenden Romanstelle und an einer Filmabbildung.</p></div><div><h3>Filmplakate erzählen anders</h3><p>Ein Plakat verspricht eine Erfahrung, ohne den ganzen Film abzubilden. Kinderstar, Alpenpanorama, Paarbildung oder bewaffnete Heldin sprechen jeweils andere Erwartungen an. Vergleiche die Plakate von 1937, 1952, 1955 und 2022 im Archiv.</p><p class="small">Die Bildunterschriften unterscheiden Filmstandbild, Werbemotiv und Buchillustration. Ein Klick vergrössert das Bild und öffnet den vollständigen Nachweis.</p></div></div></section>
<section id="wirkung"><p class="eyebrow">WIRKUNGSGESCHICHTE</p><h2>Vom Buch in die Welt.</h2><div class="grid"><article class="card"><h3>Übersetzung</h3><p>Übertragung verändert Anreden, Ortsbezüge, Religion und Bilder. Entscheidend ist nicht nur, was wörtlich erhalten bleibt, sondern welche Funktion im neuen Kontext verständlich wird. Französische Fortsetzungen von Charles Tritten sind von Spyris Originalbänden zu unterscheiden.</p>${cite(['osullivan','bando','dossier'])}</article><article class="card"><h3>Tourismus</h3><p>Ein literarischer Ort wird besuchbar. «Authentisch» kann geografisch passend, historisch erhalten, textnah oder emotional überzeugend bedeuten. Ein Heidihaus ist nicht das nachgewiesene Wohnhaus eines historischen Mädchens namens Heidi.</p>${cite(['tourism','tomkowiak'])}</article><article class="card"><h3>Nationale Zuschreibungen</h3><p>Ein Autostereotyp betrifft die eigene Gruppe, ein Heterostereotyp eine andere. Beide können sich verstärken, wenn eine Region das erwartete Fremdbild touristisch inszeniert. Walthers Essay zeigt, wie literarische Figuren zur Deutung solcher Zuschreibungen herangezogen werden.</p>${cite(['walther','tomkowiak'])}</article><article class="card"><h3>Behinderung und Norm</h3><p>Leskau und Nieberle fragen, wie Klaras Gehenlernen eine Normalisierung organisiert. Eine heutige Gegenlektüre prüft, ob Glück und Anerkennung auch ohne diesen körperlichen Wandel vorstellbar wären. Das ist eine Analyse der Erzählung, keine Diagnose realer Menschen.</p>${cite(['leskau'])}</article><article class="card"><h3>Parodie und KI</h3><p>Eine bekannte Figur kann mit wenigen Zeichen aufgerufen werden. Mad Heidi bricht Genreerwartungen; Karpis Trailerexperiment von 2023 verfremdet vertraute Motive durch generierte Bilder. Beides setzt ein Publikum voraus, das Heidi bereits wiedererkennt.</p>${cite(['madprod','karpi'])}</article><article class="card"><h3>Archiv und Erinnerung</h3><p>2023 wurden die Heidi- und Johanna-Spyri-Archive in das UNESCO-Register Memory of the World aufgenommen. Die dokumentierten Ausgaben, Bilder und Rezeptionszeugnisse ermöglichen es, Wandel nachzuweisen. Gemeint ist kein Welterbetitel für das Heididorf.</p>${cite(['unesco','archiv'])}</article></div></section>
<section id="stationen" class="workshops"><p class="eyebrow">DIE LERNWERKSTÄTTEN</p><h2>Aus Wissen wird Untersuchung.</h2><p class="section-intro">Wähle eine Werkstatt, bearbeite den Auftrag und öffne den Erwartungshorizont erst danach. Er bietet Kriterien und mögliche Deutungen, keine einzig richtige Interpretation.</p><div class="station-list">${stations.map(s=>`<details class="station" id="station-${s.n}"><summary><span class="station-n">${s.n}</span><span><span class="station-title">${s.title}</span><span class="station-meta">${s.level} · ${s.time}</span></span><span class="plus" aria-hidden="true">+</span></summary><div class="station-body"><p class="station-intro">${s.intro}</p><div class="split"><div><h4>Dein Auftrag</h4><p>${s.task}</p><h4>Dein Ergebnis</h4><p>${s.product}</p></div><div><details class="inner-details"><summary>Starthilfe öffnen</summary><p>${s.help}</p></details><details class="inner-details"><summary>Erwartungshorizont öffnen</summary><p>${s.answer}</p></details>${cite(s.refs)}</div></div></div></details>`).join('')}</div></section>
<section id="projekt"><p class="eyebrow">ABSCHLUSS & TRANSFER</p><h2>Deine Heidi-Ausstellung.</h2><div class="split"><div><p class="lead">Stelle fünf Objekte zusammen, die zeigen, wie Heidi ihre Bedeutung verändert.</p><ol><li>Eine Romanstelle oder historische Ausgabe.</li><li>Eine Übersetzung oder Illustration.</li><li>Zwei kontrastierende Film- oder Serienfassungen.</li><li>Ein Objekt aus Werbung, Tourismus oder Parodie.</li></ol><p>Jedes Objekt erhält einen Kommentar von etwa 100 Wörtern: Was wurde übernommen? Was verändert? Für welches Publikum? Auf welchen Belegen beruht deine Aussage? Schliesslich beantwortest du die Leitfrage in 300 Wörtern.</p></div><div class="rubric"><h3>Woran du Qualität erkennst</h3><p><b>Beobachtung · 0–3 Punkte</b><br>Konkrete Textstellen und Bildmerkmale statt pauschaler Eindrücke.</p><p><b>Vergleich · 0–3 Punkte</b><br>Gemeinsame Kriterien und erklärte dramaturgische Funktionen.</p><p><b>Kontext & Quellen · 0–3 Punkte</b><br>Belegter historischer Bezug; Quellentyp und Grenzen benannt.</p><p><b>Deutung · 0–3 Punkte</b><br>Nachvollziehbare These und ernst genommene Gegenlesart.</p><p class="small">0 = fehlt · 1 = ansatzweise · 2 = schlüssig · 3 = präzise und differenziert. Die zwölf Punkte sind ein Vorschlag zur Rückmeldung, keine vorgegebene Schulnote.</p></div></div></section>
<section id="notizen" class="blue-section"><p class="eyebrow">ARBEITSBLATT</p><h2>Beobachtung vor Behauptung.</h2><p>Trage deine Untersuchung hier ein und lade sie als Textdatei herunter. Die Eingaben bleiben nur in diesem geöffneten Fenster; vor dem Schliessen sichern.</p><div class="note-grid"><label>Untersuchtes Material, Fassung und Zeitcode<textarea id="note-material" placeholder="Film, Regie, Jahr, Sprache, Schnittfassung; Szene von … bis …"></textarea></label><label>Beobachtung<textarea id="note-observation" placeholder="Was sehe oder höre ich genau? Was steht im Text?"></textarea></label><label>Dramaturgische Funktion und historische Einordnung<textarea id="note-analysis" placeholder="Wie verändert dies Konflikt, Perspektive, Tempo oder Schluss? Welche Quelle stützt den historischen Bezug?"></textarea></label><label>These, Gegenlesart und offene Frage<textarea id="note-thesis" placeholder="Meine These … Eine andere Erklärung … Noch zu prüfen …"></textarea></label></div><button id="download-notes" class="button">Notizen herunterladen ↓</button> <a href="Arbeitsheft_Heidi.md" download>Alle Aufträge als Arbeitsheft ↓</a><p id="note-status" class="small" role="status"></p></section>
<section id="wissen"><p class="eyebrow">OFFENE LERNFRAGEN</p><h2>Gedanken formulieren.<br>Mit Feedback weiterdenken.</h2><p class="section-intro">Antworte in deinen eigenen Worten. Du erhältst Rückmeldungen zu erkennbaren Gedanken und Anregungen zum Weiterarbeiten. Synonyme, Umschreibungen und kleinere Tippfehler werden berücksichtigt. Es gibt keine Punkte und keine vorgegebene Wortwahl.</p><p class="small">Das automatische Feedback arbeitet mit hinterlegten Bedeutungsfeldern. Es kann ungewöhnliche, aber treffende Deutungen übersehen und ersetzt keine gemeinsame Textbesprechung. Deine Antworten bleiben in diesem Fenster; sichere sie vor dem Schliessen.</p><div class="open-checks">${HeidiFeedback.tasks.map((q,i)=>`<article class="open-card" id="check-${q.id}"><span class="number">${String(i+1).padStart(2,'0')} / IN EIGENEN WORTEN</span><h3 id="question-${q.id}">${q.q}</h3><p id="guide-${q.id}" class="small">${q.guide}</p><label class="answer-label" for="answer-${q.id}">Deine Antwort</label><textarea id="answer-${q.id}" data-answer="${q.id}" aria-labelledby="question-${q.id}" aria-describedby="guide-${q.id}" maxlength="6000" rows="5" placeholder="Mein Gedanke dazu …"></textarea><div class="answer-actions"><button data-feedback="${q.id}">Feedback erhalten</button><span class="small">Überarbeiten und erneut prüfen ist jederzeit möglich.</span></div><div id="feedback-${q.id}" class="open-feedback" role="status" aria-live="polite" aria-atomic="true"></div><details class="answer-example"><summary>Eine mögliche Antwort zum Vergleichen</summary><p>${q.example}</p><p class="small">Dies ist ein Beispiel, kein verbindlicher Wortlaut. Eine anders formulierte und gut begründete Antwort kann genauso tragfähig sein.</p></details>${cite(q.refs)}</article>`).join('')}</div><button id="download-answers" class="button">Antworten und Feedback herunterladen ↓</button><p id="answers-status" role="status" class="small"></p></section>
<section id="lehrperson"><p class="eyebrow">FÜR DIE UNTERRICHTSPLANUNG</p><h2>Vertiefen, ohne alles sehen zu müssen.</h2><div class="split"><div><h3>Ein tragfähiges Kernkorpus</h3><p>Für den Filmfokus bieten sich Roman, 1937, 1952, 1974 und 2015 an. Mit 1955 lässt sich ein kollektiver Höhepunkt untersuchen; 2001 öffnet den Vergleich der Zeitwelten, 2025 die ökologische Erweiterung. Weitere Fassungen können in arbeitsteiligen Gruppen bearbeitet werden.</p><p>Als Vergleichsszenen eignen sich der erste Aufstieg, das erste Gespräch mit dem Grossvater, die Ankunft in Frankfurt, eine Heimwehsequenz und der Schluss. Nicht jede Fassung enthält dieselben Ereignisse: Auch das Fehlen ist ein Befund.</p></div><div><h3>Differenzierung</h3><p><b>Grundlage:</b> Beobachtungsraster und zwei kurze Ausschnitte vorgeben. <b>Vertiefung:</b> Forschungstext einbeziehen und eine Deutung widerlegen lassen. <b>Transfer:</b> Eigenes Treatment oder Ausstellungskommentar mit Nachweisen verfassen.</p><p>Für eine Arbeit ohne Filmzugang genügen die bereitgestellten Texte, die Bildgalerie und die dokumentierten Produktionsaussagen. Dabei die Ergebnisse als Quellen- oder Bildanalyse bezeichnen, nicht als vollständige Filmanalyse. Mad Heidi wird über Synopsis oder geeignetes Plakat behandelt.</p></div></div></section>
<section id="quellen"><p class="eyebrow">NACHWEISE & QUELLENKRITIK</p><h2>Worauf diese Landschaft beruht.</h2><div class="source-intro"><p><b>Vier bereitgestellte Dokumente.</b> Das Dossier liefert das didaktische Grundgerüst. <em>Lesarten</em> (SIKJM, 2004) ergänzt Übersetzungs-, Rezeptions- und Filmgeschichte. Walthers Essay wird als pointiertes Rezeptionszeugnis gelesen. <em>Heidi und mehr</em> (Klimek/Wernli, 2026) ist neu einbezogen, besonders Klimeks Mehrfachadressierung, Leskau/Nieberles Perspektive auf Normalisierung und Stetters Untersuchung der Materialität.</p><p><b>Seitenangaben.</b> Literaturangaben nennen gedruckte Seiten; PDF-Links springen auf die entsprechende Dateiseite. Bei <em>Heidi und mehr</em> liegt die PDF-Seite sechs, bei <em>Lesarten</em> eine Seite höher. Walther wird nach PDF-Seiten zitiert. Die Links zu den vier Ausgangsdokumenten öffnen die lokalen, unveränderten Kopien.</p><p><b>Beleg und Deutung.</b> Filmografische Daten stammen aus den verlinkten Katalogen und Produktionsseiten. Dramaturgische Texte sind daraus und aus der Forschung entwickelte Analysen beziehungsweise ausdrücklich markierte Untersuchungshypothesen. Produzentenselbstauskünfte belegen Absichten, nicht automatisch Publikumswirkungen. Die Materialien im Dossier wurden als Quellen ausgewertet, nicht als zusätzliche Arbeitsanweisungen übernommen.</p></div><details class="source-details"><summary>Literatur und Filmquellen anzeigen (${Object.keys(sources).length})</summary><ol class="source-list">${Object.entries(sources).map(([k,s])=>`<li id="source-${k}"><a href="${s.url}" target="_blank" rel="noopener">${s.name} ↗</a></li>`).join('')}</ol></details><details class="source-details"><summary>Bildnachweise und Nutzungsangaben anzeigen</summary><p>Filmabbildungen dienen hier der vergleichenden Analyse. Eine angegebene Quelle ist keine freie Lizenz. Die lokal beigelegten Originaldokumente und Bilder sind nicht als frei veröffentlichbares Bildpaket ausgewiesen.</p><div class="image-credits">${images.filter(i=>i.path).map(i=>`<p><b>${esc(i.caption)}</b><br>${esc(i.credit)}<br><a href="${i.source}" target="_blank" rel="noopener">Quellseite ↗</a>${i.licenseUrl?` · <a href="${i.licenseUrl}">Lizenz ↗</a>`:''}</p>`).join('')}</div></details><p class="small">Redaktionsstand: 19. September 2026. Filmarchiv: systematischer Recherchebestand mit separaten Registern für Schnittfassungen, Grenzfälle und Ankündigungen. Datierungs- und Zuordnungsfragen sind sichtbar markiert. Externe Angebote und Verfügbarkeiten können sich ändern.</p></section>`;
function clipEmbed(c) {
 if(c.provider==='youtube'){const params=new URLSearchParams({rel:'0',playsinline:'1'});if(c.start!==undefined)params.set('start',c.start);if(c.end!==undefined)params.set('end',c.end);return 'https://www.youtube-nocookie.com/embed/'+c.id+'?'+params;}
 if(c.provider==='vimeo')return 'https://player.vimeo.com/video/'+c.id+'?dnt=1';
 return c.embed;
}
function renderClipCoverage(){const available=films.filter(f=>f.video||f.clip),missing=films.filter(f=>!f.video&&!f.clip);return `<aside class="clip-coverage"><p class="eyebrow">VIDEOABDECKUNG · STAND 19.09.2026</p><h3>${available.length} von ${films.length} Produktionen mit Video eingebunden</h3><p>Ein lokales Fragment, der vollständige Realfilm von 2015 und ${films.filter(f=>f.clip).length} externe Player. Die ${missing.length} noch offenen Cliprecherchen sind unten einzeln benannt. Die zusätzlichen Schnittfassungen, Recherchefälle und angekündigten Werke zählen nicht als separat mit Clips abgedeckt.</p><details><summary>Welche ${missing.length} Clips fehlen noch?</summary><ul>${missing.map(f=>`<li><a href="#film-${f.id}" data-show-film="${f.id}">${esc(f.year)} · ${esc(f.title)}</a>: ${esc(f.clipGap)}</li>`).join('')}</ul></details><p class="small">Externe Videos laden erst auf Klick. Verfügbarkeit, Werbung und regionale Einschränkungen bestimmt der jeweilige Anbieter. Ein Trailer belegt die Vermarktung und einzelne Bilder, nicht die Dramaturgie des gesamten Films. <a href="Clipnachweise_Heidi.json" download>Clipverzeichnis herunterladen</a></p></aside>`;}
function renderFullFilm(f){const v=f.fullVideo;if(!v)return '';return `<figure class="film-fragment full-film"><video controls playsinline preload="none" aria-label="${esc(f.title+' ('+f.year+') · vollständiger Realfilm')}"><source src="${esc(v.url)}" type="video/mp4">Bitte den Film über den Link darunter öffnen.</video><figcaption><strong>${esc(v.label)}</strong><p>${esc(v.note)}</p><a href="${esc(v.url)}" target="_blank" rel="noopener">Vollständigen Film separat öffnen ↗</a></figcaption></figure>`;}
function renderFilmClip(f){
 const c=f.clip;if(!c)return f.video?'':`<div class="clip-gap"><strong>Clip fehlt noch</strong><p>${esc(f.clipGap||'Noch keine konkrete Videoquelle überprüft.')}</p></div>`;
 return `<figure class="film-clip"><div class="clip-stage" id="clip-stage-${f.id}"><button type="button" class="clip-load" data-load-clip="${f.id}"><span aria-hidden="true">▶</span>${esc(c.label)}<small>Video hier laden · ${esc(c.provider==='mp4'?'Traileranbieter':c.provider==='youtube'?'YouTube':'Vimeo')}</small></button></div><figcaption><strong>${esc(c.label)}</strong><br>${esc(c.language)} · ${esc(c.author)}<p>${esc(c.note)}</p><a href="${esc(c.url)}" target="_blank" rel="noopener">Video beim Anbieter öffnen ↗</a>${c.source!==c.url?` · <a href="${esc(c.source)}" target="_blank" rel="noopener">Herkunft prüfen ↗</a>`:''}</figcaption></figure>`;
}
function loadFilmClip(id){const f=films.find(f=>f.id===id),c=f?.clip,stage=$('#clip-stage-'+id);if(!c||!stage)return;
 stage.innerHTML=c.provider==='mp4'?`<video controls playsinline preload="metadata" aria-label="${esc(f.title+' · '+c.label)}"><source src="${esc(c.embed)}" type="video/mp4">Bitte den Link zum Traileranbieter nutzen.</video>`:`<iframe src="${esc(clipEmbed(c))}" title="${esc(f.title+' ('+f.year+') · '+c.label)}" allow="fullscreen; encrypted-media; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`;
}
function renderFilms(filter='Alle') {const query=($('#film-search')?.value||'').toLocaleLowerCase('de').trim();const list=films.filter(f=>(filter==='Alle'||f.kind===filter)&&(!query||[f.title,f.year,f.director,f.country,f.mode,f.facts].join(' ').toLocaleLowerCase('de').includes(query))); $('#film-count').textContent=`${list.length} ${list.length===1?'Produktion':'Produktionen'}`;$('#film-grid').innerHTML=list.map(f=>`<article class="film-card" id="film-${f.id}">${pic(f.id,'film-image')}<div class="film-head"><span class="film-year">${f.year}</span><span class="pill">${f.kind}</span></div><h3>${f.title}</h3><p class="film-director">${f.director}<br><span>${f.country}</span></p><h4>${f.mode}</h4><p>${f.facts}</p>${additionalImageSources[f.id]?`<p class="source"><a href="${esc(additionalImageSources[f.id].source)}" target="_blank" rel="noopener">${esc(additionalImageSources[f.id].caption)} · externe Bildquelle ↗</a></p>`:''}<p class="film-access"><a href="${esc(f.access?.url||sources[f.refs[0]].url)}" target="_blank" rel="noopener">${esc(f.access?.label||'Quellen- / Katalognachweis')} ↗</a><span>${esc(f.video?'Lokales Filmfragment':f.clip?'Videoplayer unten':f.access?.type||'Kein Video eingebettet')}</span></p>${f.video?`<figure class="film-fragment"><video controls playsinline preload="metadata" aria-label="Heidi of the Alps (1920): bereitgestelltes Filmfragment" aria-describedby="fragment-caption-${f.id}"><source src="${f.video}" type="video/mp4">Das Video kann hier nicht abgespielt werden. <a href="${f.video}">Fragment als MP4 öffnen</a>.</video><figcaption id="fragment-caption-${f.id}"><strong>Filmfragment · 2:30 Minuten</strong><br>Bereitgestellte Datei zu «Heidi of the Alps» (1920). Die Herkunft der Digitalisierung ist nicht dokumentiert. <a href="${f.video}" target="_blank" rel="noopener">Video separat öffnen ↗</a></figcaption></figure>`:''}${renderFullFilm(f)}${renderFilmClip(f)}<details><summary>Analyse & Lernauftrag <span aria-hidden="true">+</span></summary><div class="film-detail"><span class="mini-label">DRAMATURGISCHE LESART</span><p>${f.analysis}</p><span class="mini-label">HISTORISCHER KONTEXT</span><p>${f.context}</p><div class="film-task"><b>${f.question}</b><p>${f.scene}</p></div>${cite(f.refs)}</div></details><button class="compare-button" data-compare="${f.id}">Diese Fassung vergleichen ↗</button></article>`).join('')||'<p class="film-empty" role="status">Keine passende Produktion. Suche kürzen oder den Filter «Alle» wählen.</p>';}
function renderCompare(){const a=films.find(f=>f.id===$('#compare-a').value),b=films.find(f=>f.id===$('#compare-b').value);$('#comparison').innerHTML=`<div class="table-wrap"><table><caption>${esc(a.year+' / '+b.year)} · Vergleich nach gemeinsamen Kriterien</caption><thead><tr><th scope="col">Untersuchungsachse</th><th scope="col">${a.title} (${a.year})</th><th scope="col">${b.title} (${b.year})</th></tr></thead><tbody>${['Konflikt','Erzählbogen','Formale Mittel','Historischer Anschluss'].map((x,i)=>`<tr><th scope="row">${x}</th><td>${a.compare[i]}</td><td>${b.compare[i]}</td></tr>`).join('')}<tr><th scope="row">Prüffrage</th><td>${a.question}</td><td>${b.question}</td></tr></tbody></table></div><p class="small">Vergleichsgrundlagen: <a href="#film-${a.id}" data-show-film="${a.id}">${a.year} · ${a.director}</a> / <a href="#film-${b.id}" data-show-film="${b.id}">${b.year} · ${b.director}</a>. ${a.id===b.id?'Du hast dieselbe Fassung gewählt. Wähle eine zweite für einen Kontrast.':''}</p>`;}
renderFilms();renderCompare();
$('#film-search').addEventListener('input',()=>renderFilms(document.querySelector('[data-filter][aria-pressed="true"]')?.dataset.filter||'Alle'));
$('#compare-a').addEventListener('change',renderCompare);$('#compare-b').addEventListener('change',renderCompare);
document.addEventListener('click',e=>{const clip=e.target.closest('[data-load-clip]');if(clip)loadFilmClip(clip.dataset.loadClip);const filter=e.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===filter)));renderFilms(filter.dataset.filter);}const compare=e.target.closest('[data-compare]');if(compare){$('#compare-a').value=compare.dataset.compare;renderCompare();$('#labor').scrollIntoView({behavior:'smooth'});}const show=e.target.closest('[data-show-film]');if(show){$('#film-search').value='';document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter==='Alle')));renderFilms();}const img=e.target.closest('[data-image]');if(img){openImage(img.dataset.image);}});
$('#download-notes').addEventListener('click',()=>{const labels=['Material / Fassung / Zeitcode','Beobachtung','Dramaturgie und historischer Kontext','These / Gegenlesart / offene Frage'];const ids=['material','observation','analysis','thesis'];const t='HEIDI · UNTERSUCHUNGSPROTOKOLL\n\n'+ids.map((id,i)=>labels[i]+'\n'+$('#note-'+id).value).join('\n\n');const blob=new Blob([t],{type:'text/plain;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='Heidi_Untersuchungsprotokoll.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);$('#note-status').textContent='Die Textdatei wurde zum Herunterladen bereitgestellt.';});
const dialog=document.createElement('dialog');dialog.id='image-dialog';dialog.innerHTML='<button class="close-dialog" aria-label="Bildansicht schliessen">Schliessen ×</button><div id="dialog-content"></div>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});
function openImage(id){const i=images.find(i=>i.id===id);$('#dialog-content').innerHTML=`<img src="${i.path}" alt="${esc(i.caption)}"><p><b>${esc(i.caption)}</b><br>${esc(i.credit)}<br><a href="${i.source}" target="_blank" rel="noopener">Original und Bildnachweis ↗</a>${i.licenseUrl?` · <a href="${i.licenseUrl}">Lizenz</a>`:''}</p>`;dialog.showModal();}
let savedDetails=[];window.addEventListener('beforeprint',()=>{savedDetails=[...document.querySelectorAll('details')].map(d=>[d,d.open]);savedDetails.forEach(([d])=>d.open=true);});window.addEventListener('afterprint',()=>savedDetails.forEach(([d,o])=>d.open=o));
if(location.hash)setTimeout(()=>document.getElementById(location.hash.slice(1))?.scrollIntoView(),50);
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 try{Promise.resolve(document.modelContext.registerTool({name:'compare_heidi_versions',title:'Heidi-Fassungen vergleichen',description:'Wählt zwei Fassungen in der sichtbaren Vergleichsmatrix. Verändert nur die lokale Ansicht.',inputSchema:{type:'object',properties:{first:{type:'string',enum:films.map(f=>f.id)},second:{type:'string',enum:films.map(f=>f.id)}},required:['first','second'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!films.some(f=>f.id===input.first)||!films.some(f=>f.id===input.second)||Object.keys(input).some(k=>!['first','second'].includes(k)))throw new Error('Zwei gültige Film-IDs sind erforderlich.');$('#compare-a').value=input.first;$('#compare-b').value=input.second;renderCompare();$('#labor').scrollIntoView();return {first:input.first,second:input.second,criteria:['Konflikt','Erzählbogen','Formale Mittel','Historischer Anschluss']};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

const answerHistory=new Map();
function renderLearningFeedback(id){
 const text=$('#answer-'+id).value,result=HeidiFeedback.evaluate(id,text),old=answerHistory.get(id);
 const edited=old&&old.text!==text;const attempts=old?old.attempts+(edited?1:0):1;
 const gained=edited?result.recognized.filter(x=>!old.result.recognized.some(y=>y.id===x.id)):[];
 answerHistory.set(id,{text,result,attempts});
 const out=$('#feedback-'+id);out.dataset.state=result.state;
 out.innerHTML=`<h4>${esc(result.message)}</h4>${gained.length?`<p class="revision-note">In deiner Überarbeitung zusätzlich erkennbar: ${gained.map(x=>esc(x.label)).join('; ')}.</p>`:''}${result.recognized.length?`<h5>Das greift deine Antwort auf</h5><ul>${result.recognized.map(x=>`<li>${esc(x.praise)}<blockquote>«${esc(x.evidence)}»</blockquote></li>`).join('')}</ul>`:''}${result.conflicts.length?`<h5>Diese Aussage prüfen</h5><ul>${result.conflicts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="small">Falls du eine fremde Behauptung zitierst oder widerlegst, kennzeichne diesen Bezug ausdrücklich. Die automatische Rückmeldung kann solche Bezüge missverstehen.</p>`:''}${result.missing.length?`<h5>${result.recognized.length?'Hier kannst du weiterarbeiten':'Hilfen zum Präzisieren'}</h5><ul>${result.missing.slice(0,attempts>1?3:2).map(x=>`<li>${esc(x.hint)}</li>`).join('')}</ul><p class="small">«Noch nicht erkannt» bedeutet nicht «falsch». Falls du den Gedanken bereits anders ausgedrückt hast, gleiche ihn mit der Quelle ab.</p>`:''}${result.state==='covered'?'<p>Prüfe abschliessend, ob deine Begründung und deine Quellenbezüge tragen. Erkannte Aspekte sind noch keine vollständige Bewertung deiner Argumentation.</p>':''}${result.uncertain?'<p class="small">Du formulierst vorsichtig. Unterscheide belegte Angaben von offenen Deutungen und halte fest, was du noch prüfen möchtest.</p>':''}`;
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-feedback]');if(b)renderLearningFeedback(b.dataset.feedback);});
document.addEventListener('input',e=>{const id=e.target.dataset.answer;if(!id||!answerHistory.has(id))return;const out=$('#feedback-'+id);out.dataset.state='stale';out.textContent='Deine Antwort wurde verändert. Hole erneut Feedback, damit sich die Rückmeldung auf die aktuelle Fassung bezieht.';});
$('#download-answers').addEventListener('click',()=>{
 const text='HEIDI · OFFENE LERNFRAGEN\n\n'+HeidiFeedback.tasks.map(q=>{const answer=$('#answer-'+q.id).value;const stored=answerHistory.get(q.id);const current=stored&&stored.text===answer;return q.q+'\n\nMeine Antwort:\n'+(answer||'[noch offen]')+'\n\nFeedback:\n'+(current?$('#feedback-'+q.id).innerText:'Für diese Fassung liegt noch kein aktuelles Feedback vor.');}).join('\n\n---\n\n');
 const link=document.createElement('a');link.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));link.download='Heidi_Offene_Lernfragen.txt';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000);$('#answers-status').textContent='Antworten und aktuelles Feedback wurden zum Herunterladen bereitgestellt.';
});
